import {PLANNING_DEFAULTS} from './planning.js';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function planningControls(state){
 const p={...PLANNING_DEFAULTS,...state.planning};
 const check=(key,label)=>`<label class="planning-check"><input type="checkbox" data-planning="${key}" ${p[key]?'checked':''}> ${label}</label>`;
 const field=(key,label,min,max,unit)=>`<div class="field"><label for="plan-${key}">${label}</label><div class="input-wrap">${unit==='$'?'<span>$</span>':''}<input id="plan-${key}" type="number" data-planning="${key}" min="${min}" max="${max}" step="${unit==='age'?'1':'any'}" value="${p[key]}">${unit==='$'?'':`<span>${unit}</span>`}</div></div>`;
 return `<div class="planning-link">${check('useBudgetSavings','Use Budget savings for matching accounts')}<p class="inline-note">Reuses retirement, Roth, brokerage, emergency-fund and education contributions. Other accounts keep their manual amounts.</p></div><details class="projection-assumptions"><summary>Employer match & future income</summary><p class="inline-note">Optional assumptions. Income checks whether the plan can be funded; it is not automatically added to your balances.</p><div class="fields">${field('employerMatchMonthly','Vested employer match / month',0,1e9,'$')}${field('incomeGrowthPct','Annual income growth',-99,100,'%')}${field('contributionGrowthPct','Annual contribution growth',-99,100,'%')}</div><p class="inline-note">Employer money goes to the retirement account and does not reduce take-home pay. Enter only the match you expect to receive and keep. Contribution growth is a separate choice.</p>${check('incomeChangeEnabled','Model a future change in annual income')}<div class="fields">${field('incomeChangeAge','Income changes at age',18,120,'age')}${field('incomeChangeAnnual','New annual gross income',0,1e9,'$')}</div><p class="inline-note">The new annual amount replaces income at that age; annual growth continues afterward. Wages-only tax assumptions still apply. This does not model pension or Social Security tax rules.</p>${check('inflationAdjustedWithdrawals','Increase withdrawals with inflation')}<p class="inline-note">When enabled, the withdrawal amount is in today’s dollars and increases from today with your inflation assumption.</p></details>`;
}
export function restrictedControl(r,group){if(group!=='investments')return '';return `<p class="inline-note">Account type: ${esc(r.accountType||'other')}. <label><input type="checkbox" data-withdrawal-account="${esc(r.id)}" ${r.allowGeneralWithdrawals?'checked':''}> Include in general-spending withdrawals</label></p>`;}
export function planningSummary(state,p){const f=p.funding;if(!f)return '';return `<section class="panel funding-summary"><h2>Can this plan be funded?</h2><p>${f.shortfall>.01?`${money(f.shortfall)} / month is not covered by the selected Budget.`:`Current modeled funding leaves ${money(f.remaining)} / month.`}</p>${p.firstFundingShortfall&&p.firstFundingShortfall.year>0?`<p class="notice-box danger">Funding first falls short at age ${state.home.age+p.firstFundingShortfall.year}: ${money(p.firstFundingShortfall.shortfall)} / month.</p>`:''}<p class="inline-note">Contributions and debt payments already in Budget are counted once. Employer match is separate. Projections still show your assumptions even when funding falls short.</p>${f.warnings?.length?`<ul>${f.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<details><summary>Funding details</summary><p>Your contributions: ${money(f.plannedContributions)} / month<br>Employer match: ${money(f.employerMatch)} / month<br>Forecast debt payments: ${money(f.debtPayments)} / month</p><p class="inline-note">Uses ${state.budget.housing==='proposed'?'proposed home':'current housing'} from Budget. Expenses remain at entered amounts unless the model explicitly adjusts them.</p>${p.fundingPoints?.length?`<div class="table-scroll" tabindex="0" role="region" aria-label="Annual funding figures"><table><thead><tr><th>Year</th><th>Funding remaining / month</th></tr></thead><tbody>${p.fundingPoints.map(x=>`<tr><td>${x.year}</td><td>${money(x.remaining??x.funding?.remaining??0)}</td></tr>`).join('')}</tbody></table></div>`:''}</details><button class="text-btn" data-mode="budget">Review Budget →</button></section>`;}

